import re,glob,collections
def parse(files):
    res=collections.defaultdict(list); cost=collections.defaultdict(float); cur=None
    for f in files:
        for line in open(f,errors='ignore'):
            m=re.match(r'▶ (\S+)/(r\d) (S\d+|C8|QW\d+|orchestrator|drive|RUN)',line)
            if m: cur=(m.group(1),m.group(2),m.group(3)); continue
            m=re.search(r'ok (\S+) tests (\d+)/(\d+)',line)
            if m and cur:
                c=re.search(r'reported_cost_usd":([0-9.]+)',line)
                if c: cost[cur[0]]+=float(c.group(1))
                if cur[2] in ('S10','orchestrator','drive'): res[cur[0]].append((int(m.group(2)),int(m.group(3))))
    return res,cost
for name,files in [('CHAIN A (round-2*, excl chainb/qw/c6/c8/bridge)',[f for f in glob.glob('round-2-*.log')+glob.glob('round-2.log') if not any(x in f for x in ['chainb','qw','c6','c8','bridge'])]),('CHAIN B',glob.glob('round-2-chainb-*.log'))]:
    r,c=parse(files); print('==',name)
    for arm,v in sorted(r.items()):
        p=[a/b for a,b in v if b]; 
        print(f'  {arm:22s} final pass {sum(p)/len(p)*100:5.1f}%  reps={len(p)}  ' + ' '.join(f'{a}/{b}' for a,b in v) + (f'  cost ${c[arm]:.0f}' if c.get(arm) else ''))
